import { registry } from "@web/core/registry";
import { Base } from "@point_of_sale/app/models/related_models";

export class LoyaltyProgram extends Base {
    static pythonModel = "loyalty.program";

    /**
     * Points this order earns for the program from its rules (the "won" points).
     * mirror of *models/loyalty_program.py* LoyaltyProgram._get_pos_order_points
     * @param {object} order
     * @returns {number} the points generated by the order
     */
    getEarnedPoints(order) {
        if (this.program_type === "coupons") {
            return 0;
        }
        if (order.isRefund && !this.is_payment_program) {
            return this._getRefundReversalPoints(order).issued;
        }
        let points = 0;
        for (const rule of this.rule_ids) {
            points += rule.getPoints(order);
        }
        return points;
    }

    /**
     * Reverse what the refunded lines' original order earned and spent for this
     * program, in proportion to the refunded amount.
     * mirror of *models/pos_order.py* PosOrder._get_refund_reversal_points
     * @param {object} order the refund order
     * @returns {{issued: number, used: number}} the (negative) points to reverse
     */
    _getRefundReversalPoints(order) {
        const isTopupLine = (line) =>
            line.payment_program_id || line.card_id || line.refunded_orderline_id?.card_id;
        const linesByOrigin = new Map();
        for (const line of order.getOrderlines()) {
            const originLine = line.refunded_orderline_id;
            if (
                line.is_reward_line ||
                line.isTipLine() ||
                isTopupLine(line) ||
                !originLine?.order_id
            ) {
                continue;
            }
            const group = linesByOrigin.get(originLine.order_id) || [];
            group.push(line);
            linesByOrigin.set(originLine.order_id, group);
        }
        let issued = 0;
        let used = 0;
        for (const [originOrder, refundLines] of linesByOrigin) {
            const originBase = originOrder
                .getOrderlines()
                .filter((line) => !line.is_reward_line && !line.isTipLine() && !isTopupLine(line))
                .reduce((total, line) => total + line.linePriceTaxIncluded, 0);
            if (!originBase) {
                continue;
            }
            let refundedBase = 0;
            for (const line of refundLines) {
                const originLine = line.refunded_orderline_id;
                const originQty = originLine.getQuantity();
                if (!originQty) {
                    continue;
                }
                refundedBase += originLine.linePriceTaxIncluded * (-line.getQuantity() / originQty);
            }
            const ratio = refundedBase / originBase;
            issued -= this.getEarnedPoints(originOrder) * ratio;
            used -= this.getSpentPoints(originOrder) * ratio;
        }
        return { issued, used };
    }

    /**
     * Points already sitting on the program's cards that this order can spend:
     * a coupon redeemed by code, or the customer's nominative card.
     * @param {object} order
     * @returns {number} the card balance available to the order
     */
    getAvailablePoints(order) {
        if (
            this.program_type === "coupons" &&
            this.rule_ids.length &&
            !this.rule_ids.some((rule) => rule.isFulfilled(order))
        ) {
            return 0;
        }
        let points = 0;
        for (const card of order.models["loyalty.card"].filter(
            (card) => card.program_id?.id === this.id && !card.isExpired()
        )) {
            if (
                order.applied_codes.includes(card.code) ||
                (this.is_nominative && card.partner_id?.id === order.partner_id?.id)
            ) {
                points += card.points;
            }
        }
        return points;
    }

    /**
     * Points this order has already spent on the program's rewards (the sum of
     * the reward lines' points_cost).
     * @param {object} order
     * @returns {number} the points spent on this order
     */
    getSpentPoints(order) {
        if (order.isRefund && !this.is_payment_program) {
            return this._getRefundReversalPoints(order).used;
        }
        let points = 0;
        for (const line of order.getOrderlines()) {
            if (line.is_reward_line && line.reward_id?.program_id?.id === this.id) {
                points += line.points_cost;
            }
        }
        return points;
    }

    /**
     * Points still usable on this program's rewards for the order: earned + card
     * balance, minus what has already been spent on rewards this order.
     * @param {object} order
     * @returns {number}
     */
    getPoints(order) {
        if (this.applies_on === "future") {
            return this.getAvailablePoints(order) - this.getSpentPoints(order);
        }
        return this.getNewBalance(order);
    }

    getNewBalance(order) {
        return (
            this.getEarnedPoints(order) +
            this.getAvailablePoints(order) -
            this.getSpentPoints(order)
        );
    }
}

registry.category("pos_available_models").add(LoyaltyProgram.pythonModel, LoyaltyProgram);
